def getattr_static(obj, attr, default=_sentinel):
    """Retrieve attributes without triggering dynamic lookup via the
       descriptor protocol,  __getattr__ or __getattribute__.

       Note: this function may not be able to retrieve all attributes
       that getattr can fetch (like dynamically created attributes)
       and may find attributes that getattr can't (like descriptors
       that raise AttributeError). It can also return descriptor objects
       instead of instance members in some cases. See the
       documentation for details.

       Returns a tuple `(attr, is_get_descriptor)`. is_get_descripter means that
       the attribute is a descriptor that has a `__get__` attribute.
    """
    instance_result = _sentinel
    if not _is_type(obj):
        klass = type(obj)
        dict_attr = _shadowed_dict(klass)
        if (dict_attr is _sentinel or type(dict_attr) is types.MemberDescriptorType):
            instance_result = _check_instance(obj, attr)
    else:
        klass = obj
    klass_result = _check_class(klass, attr)
    if (instance_result is not _sentinel and klass_result is not _sentinel):
        if (_safe_hasattr(klass_result, '__get__') and _safe_is_data_descriptor(klass_result)):
            return (klass_result, True)
    if instance_result is not _sentinel:
        return (instance_result, False)
    if klass_result is not _sentinel:
        return (klass_result, _safe_hasattr(klass_result, '__get__'))
    if obj is klass:
        for entry in _static_getmro(type(klass)):
            if _shadowed_dict(type(entry)) is _sentinel:
                try:
                    return (entry.__dict__[attr], False)
                except KeyError:
                    pass
    if default is not _sentinel:
        return (default, False)
    raise AttributeError(attr)

jedi.inference.compiled.getattr_static._:
def _check_class(klass, attr):
    for entry in _static_getmro(klass):
        if _shadowed_dict(type(entry)) is _sentinel:
            try:
                return entry.__dict__[attr]
            except KeyError:
                pass
    return _sentinel

def _check_instance(obj, attr):
    instance_dict = {}
    try:
        instance_dict = object.__getattribute__(obj, '__dict__')
    except AttributeError:
        pass
    return dict.get(instance_dict, attr, _sentinel)

jedi.inference.compiled.access.safe_geta:
def safe_getattr(obj, name, default=_sentinel):
    try:
        (attr, is_get_descriptor) = getattr_static(obj, name)
    except AttributeError:
        if default is _sentinel:
            raise
        return default
    else:
        if isinstance(attr, ALLOWED_DESCRIPTOR_ACCESS):
            return getattr(obj, name)
    return attr

jedi.inference.compiled.getattr_static._:
def _shadowed_dict(klass):
    dict_attr = type.__dict__['__dict__']
    for entry in _static_getmro(klass):
        try:
            class_dict = dict_attr.__get__(entry)['__dict__']
        except KeyError:
            pass
        else:
            if not ((type(class_dict) is types.GetSetDescriptorType and class_dict.__name__ == '__dict__' and class_dict.__objclass__ is entry)):
                return class_dict
    return _sentinel

def _is_type(obj):
    try:
        _static_getmro(obj)
    except TypeError:
        return False
    return True

def _static_getmro(klass):
    mro = type.__dict__['__mro__'].__get__(klass)
    if not isinstance(mro, (tuple, list)):
        debug.warning('mro of %s returned %s, should be a tuple' % (klass, mro))
        return ()
    return mro
